              className={cn(
                "w-full h-[510px] xl:h-[570px] pointer-events-auto flex flex-col justify-between p-7 xl:p-9 border cursor-pointer relative overflow-hidden rounded-2xl transition-all duration-500",
                TAB_THEMES[activeTab].bg,
