  inquiryEmail = "hello@avara.ui",
  navColumns = DEFAULT_ARCHITECTURAL_NAV,
  socials = DEFAULT_ARCHITECTURAL_SOCIALS,
  legalLinks = DEFAULT_ARCHITECTURAL_LEGAL,
  copyrightText,
  className,
