  return (
    <footer
      style={dynamicAccent}
      className={cn(
        "w-full bg-[#f4f3ef] dark:bg-[#0c0d10] text-neutral-900 dark:text-neutral-100 border-t border-neutral-300 dark:border-neutral-800 transition-colors select-none font-sans",
